package com.primehr.operations.api;
import com.primehr.operations.api.OperationsDtos.*;import com.primehr.operations.application.OperationsService;import com.primehr.operations.application.OperationsStatusService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/operations") public class OperationsController {private final OperationsService service;private final OperationsStatusService status;private final OperationsPermissionGuard permission;private final AgencyScopeResolver agencies;public OperationsController(OperationsService s,OperationsStatusService o,OperationsPermissionGuard p,AgencyScopeResolver a){service=s;status=o;permission=p;agencies=a;}private String agency(Authentication a){return agencies.resolveAgencyId(a);}@GetMapping("/status")public OperationsStatus status(@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(PrimeHrAction.ACCESS,token);return status.status();}@PostMapping("/reconciliation-runs")public RunResponse run(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation){permission.require(PrimeHrAction.ADD,token);return service.run(agency(a),token,a.getName(),correlation,false);}@GetMapping("/reconciliation-runs")public List<RunResponse>runs(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(PrimeHrAction.ACCESS,token);return service.runs(agency(a));}@PostMapping("/reconciliation-findings/{id}/acknowledge")public FindingResponse acknowledge(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid@RequestBody FindingTransition input){permission.require(PrimeHrAction.EDIT,token);return service.acknowledge(agency(a),id,input.recordVersion(),input.note(),a.getName(),correlation);}@PostMapping("/reconciliation-findings/{id}/resolve")public FindingResponse resolve(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid@RequestBody FindingTransition input){permission.require(PrimeHrAction.EDIT,token);return service.resolve(agency(a),id,input.recordVersion(),input.note(),a.getName(),correlation);}@PostMapping("/retention-policies")public PolicyResponse policy(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@Valid@RequestBody PolicyInput input){permission.require(PrimeHrAction.ADD,token);return service.createPolicy(agency(a),input,correlation);}@GetMapping("/retention-policies")public List<PolicyResponse>policies(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(PrimeHrAction.ACCESS,token);return service.policies(agency(a));}@PostMapping("/legal-holds")public HoldResponse hold(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@Valid@RequestBody HoldInput input){permission.require(PrimeHrAction.ADD,token);return service.placeHold(agency(a),input,a.getName(),correlation);}@PostMapping("/legal-holds/{id}/release")public HoldResponse release(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid@RequestBody FindingTransition input){permission.require(PrimeHrAction.ARCHIVE,token);return service.releaseHold(agency(a),id,input.recordVersion(),input.note(),a.getName(),correlation);}@GetMapping("/legal-holds")public List<HoldResponse>holds(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(PrimeHrAction.ACCESS,token);return service.holds(agency(a));}@GetMapping("/retention-eligibility")public List<RetentionEligibility>retention(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestParam LocalDate asOf){permission.require(PrimeHrAction.ACCESS,token);return service.retentionReport(agency(a),asOf);}}
